insert into public.products (id, name, brand, description, description_tr, image_url, product_type, active_ingredients, usage_time, frequency, contraindications, skin_types, is_active) values
  ('276877c1-a1b3-54ab-ae88-704675c5f81a'::uuid, 'Hydrating Facial Cleanser', 'CeraVe', 'A non-foaming cleanser that lifts dirt and oil without stripping the skin barrier. Leaves a soft finish rather than the tight feeling many face washes give.', 'Köpürmeyen bir temizleyici; kiri ve yağı alırken cilt bariyerini soymuyor. Birçok yüz yıkama jelinin bıraktığı gerginlik hissi yerine yumuşak bir his bırakıyor.', NULL, 'cleanser', 'Ceramides, Hyaluronic Acid, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Dry','Normal','Sensitive']::text[], true),
  ('4b464323-7f4c-5d85-827b-22e97069649d'::uuid, 'Foaming Facial Cleanser', 'CeraVe', 'A gel that foams up to clear excess oil from the T zone. Built for skin that feels greasy by midday but still reacts to harsh cleansers.', 'T bölgesindeki fazla yağı almak için köpüren bir jel. Öğlen olmadan parlayan ama sert temizleyicilere de tepki veren ciltler için.', NULL, 'cleanser', 'Ceramides, Niacinamide, Hyaluronic Acid', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination','Normal']::text[], true),
  ('3d84732f-4009-5305-b46e-1d40f61699ed'::uuid, 'SA Smoothing Cleanser', 'CeraVe', 'Salicylic acid loosens the dead cells that block pores, so texture smooths out over a few weeks. Start every other night and build up.', 'Salisilik asit gözenekleri tıkayan ölü hücreleri çözüyor, birkaç hafta içinde cilt dokusu pürüzsüzleşiyor. Gün aşırı başlayıp sıklığı yavaşça artır.', 'https://images.openbeautyfacts.org/images/products/333/787/579/5456/front_en.14.400.jpg', 'cleanser', 'Salicylic Acid, Ceramides, Hyaluronic Acid', 'Night', '3-4 times a week', 'Do not combine with retinol on the same night when starting out.', ARRAY['Oily','Combination']::text[], true),
  ('701293c3-fe15-52b0-a44c-092760d9e6bf'::uuid, 'Acne Foaming Cream Cleanser', 'CeraVe', 'A cream to foam wash aimed at active breakouts on the face and back. Can bleach fabric, so use a white towel.', 'Aktif sivilcelere yönelik, kremden köpüğe dönen bir yıkama ürünü. Kumaşın rengini açabiliyor, beyaz havlu kullan.', 'https://images.openbeautyfacts.org/images/products/360/600/051/2238/front_en.4.full.jpg', 'cleanser', 'Benzoyl Peroxide 4%, Ceramides, Hyaluronic Acid', 'Night', 'Daily', 'May bleach towels and pillowcases. Introduce slowly if skin is sensitive.', ARRAY['Oily','Combination']::text[], true),
  ('dea36574-0ef3-5f77-a7f0-a4f52588c901'::uuid, 'Toleriane Hydrating Gentle Cleanser', 'La Roche-Posay', 'A milky cleanser with a very short ingredient list, made for skin that stings easily. No fragrance, no drying alcohol.', 'Çok kısa içerik listesine sahip, sütümsü bir temizleyici; kolay yanan ciltler için. Parfüm ve kurutucu alkol içermiyor.', NULL, 'cleanser', 'Niacinamide, Ceramide-3, Prebiotic Thermal Water', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive','Dry','Normal']::text[], true),
  ('44b3afe5-ae33-5dcc-a1cc-e3c757441c0f'::uuid, 'Effaclar Purifying Foaming Gel', 'La Roche-Posay', 'A soap free gel for oily, blemish prone skin. Rinses clean without the squeaky feeling that pushes oil production up again.', 'Yağlı ve sivilceye eğilimli ciltler için sabunsuz jel. Yağ üretimini yeniden tetikleyen o gıcırtılı his olmadan duruluyor.', NULL, 'cleanser', 'Zinc Pidolate, Thermal Spring Water', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination']::text[], true),
  ('ad47f0e8-5aa5-5d5a-bd9d-03a7265b7045'::uuid, 'Effaclar Clarifying Toner', 'La Roche-Posay', 'A liquid step after cleansing that keeps pores clear and evens out rough patches. Sweep it on with a cotton pad and follow with moisturiser.', 'Temizlikten sonra gelen sıvı adım; gözenekleri açık tutuyor ve pürüzlü bölgeleri eşitliyor. Pamukla uygula, ardından nemlendirici sür.', 'https://images.openbeautyfacts.org/images/products/343/342/240/6834/front_en.5.400.jpg', 'cleanser', 'Salicylic Acid, Glycolic Acid, LHA', 'Morning & Night', 'Daily', 'Increases sun sensitivity. Use sunscreen during the day.', ARRAY['Oily','Combination']::text[], true),
  ('5c0370ac-170c-53ce-a9b4-1f26d15a2843'::uuid, 'Sensibio H2O Micellar Water', 'Bioderma', 'The blue bottle most people know. Takes off makeup and sunscreen with a cotton pad and no rinsing, which suits skin that dislikes water and friction.', 'Herkesin bildiği mavi şişe. Makyajı ve güneş kremini pamukla, durulamadan alıyor; suya ve sürtünmeye tepkili ciltlere uygun.', 'https://images.openbeautyfacts.org/images/products/370/112/980/9082/front_en.3.400.jpg', 'cleanser', 'Micelles, Cucumber Extract, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive','Normal','Dry']::text[], true),
  ('34a80118-6765-5b04-bb40-45feb4741b24'::uuid, 'Sebium Foaming Gel', 'Bioderma', 'A purifying gel for skin that shines and clogs easily. Regulates oil without leaving the face parched.', 'Parlayan ve kolay tıkanan ciltler için arındırıcı jel. Yüzü kurutmadan yağ dengesini düzenliyor.', NULL, 'cleanser', 'Zinc Gluconate, Copper Sulphate, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination']::text[], true),
  ('6643685c-5b54-5b4b-8b19-72754e7493a8'::uuid, 'Sensibio H2O AR Micellar Water', 'Bioderma', 'The version made for skin with visible redness across the cheeks and nose. Same no rinse routine, with plant extracts aimed at flushing.', 'Yanaklarda ve burunda görünür kızarıklığı olan ciltler için hazırlanmış versiyon. Aynı durulamasız kullanım, kızarma için bitkisel özütlerle.', NULL, 'cleanser', 'Micelles, Ginkgo Biloba, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive','Dry']::text[], true),
  ('1a6fa930-0dc9-5084-9011-b971f6d233b0'::uuid, 'Cleanance Cleansing Gel', 'Avène', 'A soap free gel for oily skin that is also sensitive, which is a harder combination to shop for than it sounds.', 'Hem yağlı hem hassas ciltler için sabunsuz jel; kulağa geldiğinden daha zor bulunan bir kombinasyon.', 'https://images.openbeautyfacts.org/images/products/328/277/936/5529/front_fr.6.full.jpg', 'cleanser', 'Monolaurin, Avene Thermal Spring Water', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination','Sensitive']::text[], true),
  ('44d84fb1-fb7f-5ef4-a222-c95046ebcee7'::uuid, 'Gentle Milk Cleanser', 'Avène', 'A milk you can rinse off or wipe away, which makes it useful when your skin is having a reactive week.', 'Hem durulanabilen hem silinerek alınabilen bir süt; cildinin tepkili olduğu haftalarda işe yarıyor.', 'https://images.openbeautyfacts.org/images/products/328/277/905/1514/front_fr.6.full.jpg', 'cleanser', 'Avene Thermal Spring Water, Glycerin', 'Night', 'Daily', NULL, ARRAY['Dry','Sensitive','Normal']::text[], true),
  ('38b8e161-f276-523c-9ab5-df2fd30c9869'::uuid, 'Purete Thermale Mineral Micellar Water', 'Vichy', 'Mineral rich micellar water that removes the day without a second wash. Good as a quick morning cleanse before serum.', 'Mineralce zengin misel su; ikinci bir yıkamaya gerek kalmadan günü temizliyor. Serumdan önce hızlı sabah temizliği için ideal.', 'https://images.openbeautyfacts.org/images/products/333/787/567/4942/front_en.3.full.jpg', 'cleanser', 'Vichy Volcanic Water, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive','Normal','Combination']::text[], true),
  ('73c511cf-8972-5ab9-8a3d-e9a3ea48218c'::uuid, 'Gentle Skin Cleanser', 'Cetaphil', 'A low foam classic that has been in dermatology cabinets for decades. Works with or without water, which helps on travel days.', 'Onlarca yıldır dermatoloji dolaplarında duran, az köpüren bir klasik. Suyla da susuz da kullanılabiliyor, seyahatte işe yarıyor.', NULL, 'cleanser', 'Glycerin, Panthenol, Niacinamide', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive','Dry','Normal']::text[], true),
  ('b6b12f3b-bffe-5a6c-8a3a-4b80ca2b1cdf'::uuid, 'Oily Skin Cleanser', 'Cetaphil', 'The oily skin version of the same gentle formula. Cuts shine without the tight after feel.', 'Aynı yumuşak formülün yağlı cilt versiyonu. Gerginlik hissi bırakmadan parlaklığı kesiyor.', NULL, 'cleanser', 'Zinc, Glycerin, Panthenol', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination']::text[], true),
  ('56d405d0-371a-56ee-a386-b55a7239ed52'::uuid, 'Hydro Boost Cleansing Gel', 'Neutrogena', 'A water gel cleanser that puts a little hydration back as it washes. Suits skin that is dehydrated but still oily.', 'Yıkarken bir miktar nem geri veren su bazlı jel temizleyici. Susuz kalmış ama yine de yağlı ciltlere uygun.', 'https://images.openbeautyfacts.org/images/products/357/466/129/2014/front_en.5.400.jpg', 'cleanser', 'Hyaluronic Acid, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Combination','Dry']::text[], true),
  ('2389ca20-2536-539e-8921-3df786a70866'::uuid, 'Clear & Defend 1% Salicylic Acid Wash', 'Neutrogena', 'A daily wash with enough salicylic acid to keep blackheads in check. Can be left on for a minute as a short mask.', 'Siyah noktaları kontrol altında tutmaya yetecek kadar salisilik asit içeren günlük yıkama jeli. Bir dakika bekletilip kısa maske olarak da kullanılabiliyor.', NULL, 'cleanser', 'Salicylic Acid 1%', 'Morning & Night', 'Daily', 'Increases sun sensitivity. Use sunscreen during the day.', ARRAY['Oily','Combination']::text[], true),
  ('f9db2494-f628-5e93-89c0-fab83756f668'::uuid, 'Purifying Gentle Foaming Cleanser', 'Clarins', 'A creamy foam for combination skin, aimed at the oily middle without drying out the cheeks.', 'Karma ciltler için kremsi köpük; yanakları kurutmadan yağlı orta bölgeyi hedefliyor.', 'https://images.openbeautyfacts.org/images/products/338/081/042/7318/front_en.3.full.jpg', 'cleanser', 'Alpine Herbs, Tamarind Extract', 'Morning & Night', 'Daily', NULL, ARRAY['Combination','Oily']::text[], true),
  ('689ba1a2-f458-5a20-8fa1-60d921887639'::uuid, 'Squalane Cleanser', 'The Ordinary', 'Goes on as a balm and turns to oil as you massage it in, which is why it handles waterproof sunscreen so well. Rinse or wipe off.', 'Balm olarak sürülüyor, masajla yağa dönüşüyor; suya dayanıklı güneş kremini bu yüzden kolayca çıkarıyor. Durula ya da sil.', 'https://images.openbeautyfacts.org/images/products/076/991/519/4791/front_en.5.full.jpg', 'cleanser', 'Squalane, Sucrose Laurate', 'Night', 'Daily', NULL, ARRAY['Dry','Sensitive','Normal']::text[], true),
  ('af28f61b-0749-59f5-8b62-acc68c80f37a'::uuid, 'Hyseac Purifying Cleansing Gel', 'Uriage', 'A purifying gel for blemish prone skin, built around thermal water so it stays gentle enough for twice daily use.', 'Sivilceye eğilimli ciltler için arındırıcı jel; termal su bazlı olduğu için günde iki kez kullanılacak kadar yumuşak.', NULL, 'cleanser', 'Uriage Thermal Water, Zinc, TLR2-Regul', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination']::text[], true),
  ('23017ed8-4f1c-582c-9b0f-44dc57cc7817'::uuid, 'Mineral 89 Hyaluronic Acid Booster', 'Vichy', 'A thin, almost watery layer that goes under everything else and makes the rest of your routine sit better. Good first serum if you have never used one.', 'Her şeyin altına giren, neredeyse su kıvamında ince bir katman; rutinin geri kalanının daha iyi oturmasını sağlıyor. Hiç serum kullanmadıysan iyi bir başlangıç.', 'https://images.openbeautyfacts.org/images/products/333/787/554/3248/front_en.5.full.jpg', 'serum', 'Hyaluronic Acid, Vichy Volcanic Water', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Sensitive','Combination']::text[], true),
  ('722f2b3a-5cc4-5810-855d-3f33d3488ebd'::uuid, 'Liftactiv Supreme Serum 10', 'Vichy', 'Targets the fine lines that show up first around the mouth and forehead. Results build over weeks, not days.', 'Önce ağız çevresinde ve alında beliren ince çizgileri hedefliyor. Sonuç günlerle değil, haftalarla gelir.', NULL, 'serum', 'Rhamnose, Hyaluronic Acid, Vitamin C', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Combination','Dry']::text[], true),
  ('ba996499-6bd7-55fd-a602-c42c1bc81f43'::uuid, 'Aqualia Thermal Hydrating Serum', 'Vichy', 'A hydration only serum with nothing active in it, which makes it easy to slot into any routine without conflicts.', 'İçinde aktif madde olmayan, sadece nemlendiren bir serum; hiçbir rutinle çakışmadığı için kolayca araya girer.', NULL, 'serum', 'Hyaluronic Acid, Vichy Mineralizing Water', 'Morning & Night', 'Daily', NULL, ARRAY['Dry','Normal','Sensitive']::text[], true),
  ('f87dc0a8-a3fd-5dad-8c3e-f95c7a5b8043'::uuid, 'Hyalu B5 Hyaluronic Acid Serum', 'La Roche-Posay', 'Combines two sizes of hyaluronic acid with B5 for skin that looks dehydrated and a little worn out. Layers well under sunscreen.', 'İki farklı boyutta hyaluronik asidi B5 ile birleştiriyor; susuz ve yorgun görünen ciltler için. Güneş kreminin altına iyi oturuyor.', NULL, 'serum', 'Hyaluronic Acid, Vitamin B5, Madecassoside', 'Morning & Night', 'Daily', NULL, ARRAY['Dry','Sensitive','Normal']::text[], true),
  ('53c39527-122f-58d4-9d5e-d0d844907b7c'::uuid, 'Skin Renewing Vitamin C Serum', 'CeraVe', 'A morning vitamin C at a strength most people tolerate. Helps even out the marks left behind after spots clear.', 'Çoğu kişinin tolere ettiği güçte bir sabah C vitamini. Sivilceler geçtikten sonra kalan izleri eşitlemeye yardımcı oluyor.', 'https://images.openbeautyfacts.org/images/products/333/787/590/3738/front_nl.3.full.jpg', 'serum', '10% Vitamin C, Ceramides, Hyaluronic Acid', 'Morning', 'Daily', 'Store away from light and heat. Discard if it turns dark orange.', ARRAY['Normal','Combination','Dry']::text[], true),
  ('bd0dfcc9-c9e7-5242-92a7-9035f54645c9'::uuid, 'Resurfacing Retinol Serum', 'CeraVe', 'Encapsulated retinol aimed at post breakout marks and uneven texture. The ceramides in it soften the usual adjustment period.', 'Sivilce sonrası izlere ve düzensiz cilt dokusuna yönelik kapsüllenmiş retinol. İçindeki seramidler alışma dönemini yumuşatıyor.', NULL, 'serum', 'Encapsulated Retinol, Niacinamide, Ceramides', 'Night', '3-4 times a week', 'Not for use during pregnancy or breastfeeding. Increases sun sensitivity.', ARRAY['Oily','Combination','Normal']::text[], true),
  ('395e424b-233d-555d-b396-34c47a8f8bb4'::uuid, 'Granactive Retinoid 2% Emulsion', 'The Ordinary', 'A gentler retinoid form for people whose skin cannot handle classic retinol. Apply to dry skin, then moisturise.', 'Klasik retinolü kaldıramayan ciltler için daha yumuşak bir retinoid formu. Kuru cilde uygula, ardından nemlendir.', NULL, 'serum', 'Granactive Retinoid 2%, Squalane', 'Night', '3-4 times a week', 'Not for use during pregnancy or breastfeeding. Increases sun sensitivity.', ARRAY['Normal','Combination','Oily']::text[], true),
  ('720f36e4-3cc6-5a3c-b799-c099e825c96c'::uuid, 'Growth Factor 15% Solution', 'The Ordinary', 'A peptide serum for firmness and general support rather than any single visible problem. Slow and steady.', 'Tek bir görünür soruna değil, sıkılık ve genel desteğe yönelik peptit serumu. Yavaş ve istikrarlı çalışıyor.', NULL, 'serum', 'Peptides, Amino Acids', 'Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('1bcca0ef-2ef8-576c-a6df-4356f12d0f7f'::uuid, 'Pigmentbio C-Concentrate', 'Bioderma', 'Built specifically for dark patches and sun marks. Pairs vitamin C with mild acids so tone evens out from two directions.', 'Özellikle koyu lekeler ve güneş izleri için tasarlanmış. C vitaminini hafif asitlerle eşleştirerek ton eşitsizliğine iki yönden yaklaşıyor.', NULL, 'serum', 'Vitamin C, Glycolic Acid, Azelaic Acid', 'Morning', 'Daily', 'Increases sun sensitivity. Daily sunscreen is required for results.', ARRAY['Normal','Combination','Oily']::text[], true),
  ('ab9ba74d-5eea-5512-856c-3a5d245a6d01'::uuid, 'Vinoperfect Brightening Dark Spot Serum', 'Caudalie', 'A brightening serum with a grape derived active, aimed at the flat brown marks that stay after sun exposure.', 'Üzümden elde edilen aktif içeren aydınlatıcı serum; güneşten sonra kalan düz kahverengi lekelere yönelik.', 'https://images.openbeautyfacts.org/images/products/352/293/303/4329/front_en.4.full.jpg', 'serum', 'Viniferine, Grape Extract', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Sensitive','Dry']::text[], true),
  ('e0a4f4b6-37f4-59d8-958b-46edbf86f514'::uuid, 'Resveratrol Lift Firming Serum', 'Caudalie', 'A firming serum for skin that has started to lose definition along the jaw. Sits comfortably under a night cream.', 'Çene hattında belirginliğini kaybetmeye başlayan ciltler için sıkılaştırıcı serum. Gece kreminin altında rahat duruyor.', 'https://images.openbeautyfacts.org/images/products/352/293/103/1887/front_fr.7.full.jpg', 'serum', 'Resveratrol, Hyaluronic Acid, Vegan Collagen', 'Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('0744d766-37e0-5a9c-8090-07998b734d91'::uuid, 'DermoPure Triple Effect Serum', 'Eucerin', 'Works on active spots and the marks they leave at the same time, which saves a step for blemish prone skin.', 'Aktif sivilceler ve bıraktıkları izler üzerinde aynı anda çalışıyor; sivilceye eğilimli ciltler için bir adım tasarrufu.', NULL, 'serum', 'Thiamidol, Licochalcone A, Salicylic Acid', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination']::text[], true),
  ('e6b00d62-c03a-5510-88fb-371ba67706bb'::uuid, 'Double Serum Complete Age Control', 'Clarins', 'A two phase serum, one water based and one oil based, mixed in the pump as you dispense it. Rich enough to skip a separate hydrating step.', 'Biri su biri yağ bazlı iki fazlı serum; pompadan çıkarken karışıyor. Ayrı bir nemlendirme adımını atlayacak kadar zengin.', 'https://images.openbeautyfacts.org/images/products/338/081/014/9661/front_fr.4.full.jpg', 'serum', 'Turmeric, Organic Oat Sugars, 21 Plant Extracts', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('69d29b53-f926-5a79-901c-6b33393b7b91'::uuid, 'Hydro Boost Hyaluronic Acid Serum', 'Neutrogena', 'A lightweight gel serum that disappears fast, so it works well under makeup or sunscreen on warm days.', 'Hızla emilen hafif jel serum; sıcak günlerde makyajın ya da güneş kreminin altında rahat çalışıyor.', NULL, 'serum', 'Hyaluronic Acid, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Combination','Oily']::text[], true),
  ('50800d17-bcfa-514e-8d8a-063759961bbd'::uuid, 'Revitalift 1.5% Pure Hyaluronic Acid Serum', 'L''Oréal Paris', 'A straightforward hydrating serum at a price that makes daily use easy. Plumps up the fine lines that come from dryness.', 'Günlük kullanımı kolaylaştıran bir fiyata sade bir nemlendirici serum. Kurulukdan gelen ince çizgileri dolduruyor.', NULL, 'serum', '1.5% Hyaluronic Acid', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('bc925bb7-cfae-5ec8-a1fc-4883982827b3'::uuid, 'Bright Reveal Niacinamide Serum', 'L''Oréal', 'High strength niacinamide for uneven tone and visible pores. If your skin is new to niacinamide, start once a day.', 'Ton eşitsizliği ve görünür gözenekler için yüksek dozda niasinamid. Niasinamide yeniyse günde bir kez ile başla.', 'https://images.openbeautyfacts.org/images/products/360/052/411/9874/front_nl.3.full.jpg', 'serum', 'Niacinamide 12%, Amino Sulfonic Acid', 'Morning & Night', 'Daily', NULL, ARRAY['Combination','Oily','Normal']::text[], true),
  ('52a162af-3b85-5dc5-95e3-49608155002a'::uuid, 'Regenerist Retinol 24 Max Serum', 'Olay', 'A night retinol paired with B3 to reduce the flaking that usually comes with starting out.', 'Başlangıçta görülen pullanmayı azaltmak için B3 ile eşleştirilmiş gece retinolü.', NULL, 'serum', 'Retinol, Vitamin B3', 'Night', 'Daily', 'Not for use during pregnancy or breastfeeding. Increases sun sensitivity.', ARRAY['Normal','Combination','Dry']::text[], true),
  ('0e53c6d6-6b20-5ded-9df6-8a754f7a3930'::uuid, 'Age-Purify Intensive Serum', 'Filorga', 'Made for adult skin that still breaks out while showing early lines, which most acne products ignore.', 'Hem sivilcelenen hem erken çizgileri olan yetişkin ciltler için; çoğu sivilce ürününün göz ardı ettiği bir durum.', NULL, 'serum', 'NCEF Complex, Salicylic Acid, Niacinamide', 'Night', 'Daily', 'Increases sun sensitivity. Use sunscreen during the day.', ARRAY['Combination','Oily','Normal']::text[], true),
  ('c1009406-0d66-5c70-a27c-a2db5f09ffd8'::uuid, 'Effaclar Duo+ Anti-Blemish Care', 'La Roche-Posay', 'Applied over the whole area rather than dabbed on single spots. Works on the breakout and the mark it would otherwise leave.', 'Tek tek sivilcelere değil, tüm bölgeye uygulanıyor. Hem sivilceye hem geride bırakacağı ize çalışıyor.', NULL, 'treatment', 'Niacinamide, Salicylic Acid, LHA, Procerad', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination']::text[], true),
  ('c4112429-1ecb-5dd9-955d-8f5c037ce8a8'::uuid, 'Effaclar Sebum-Regulating Mask', 'La Roche-Posay', 'A clay mask for weeks when the T zone will not settle. Ten minutes is enough, longer does not help.', 'T bölgesinin bir türlü sakinleşmediği haftalar için kil maskesi. On dakika yeterli, uzatmanın faydası yok.', NULL, 'treatment', 'Kaolin, Thermal Spring Water', 'Night', '1-2 times a week', NULL, ARRAY['Oily','Combination']::text[], true),
  ('1f286fc8-50be-5d7f-af9c-dbfb89d8feeb'::uuid, 'Cicaplast Baume B5 Soothing Balm', 'La Roche-Posay', 'A thick repair balm for patches that are raw from wind, over exfoliation or a new retinol. Use it as a spot treatment, not all over.', 'Rüzgardan, aşırı peelingden ya da yeni bir retinolden tahriş olmuş bölgeler için kalın bir onarıcı balm. Tüm yüze değil, bölgesel uygula.', NULL, 'treatment', 'Panthenol 5%, Madecassoside, Shea Butter', 'Night', 'As needed', NULL, ARRAY['Sensitive','Dry']::text[], true),
  ('a4de0952-f221-5f63-9b39-a7b7c0d948a8'::uuid, 'AHA 30% + BHA 2% Peeling Solution', 'The Ordinary', 'A strong ten minute peel, once a week at most. Rinse it off on time and skip other actives that night.', 'Haftada en fazla bir kez kullanılan güçlü, on dakikalık bir peeling. Süresinde durula ve o gece başka aktif kullanma.', NULL, 'treatment', 'Glycolic Acid, Lactic Acid, Salicylic Acid', 'Night', 'Once a week', 'Do not use on broken or irritated skin. Not suitable for sensitive skin. Sunscreen is required the next day.', ARRAY['Oily','Combination','Normal']::text[], true),
  ('8c0b186a-5a1e-59f8-93f9-e83fd37e3bf2'::uuid, 'Vinoperfect Glycolic Peel Mask', 'Caudalie', 'A milder weekly peel that brightens without the sting of a strong acid. Leaves skin looking more even the next morning.', 'Güçlü asitlerin yakma hissi olmadan aydınlatan, daha ılımlı bir haftalık peeling. Ertesi sabah cilt daha eşit görünüyor.', NULL, 'treatment', 'Glycolic Acid, Viniferine, Papaya Enzymes', 'Night', '1-2 times a week', 'Increases sun sensitivity. Use sunscreen the following day.', ARRAY['Normal','Combination','Dry']::text[], true),
  ('6a00c1c9-6d86-5777-a032-4f9891fc2f41'::uuid, 'Vinoperfect Glycolic Night Cream', 'Caudalie', 'A night cream that does its exfoliating quietly while you sleep, aimed at long standing dark patches.', 'Uykudayken sessizce peeling yapan bir gece kremi; uzun süredir duran koyu lekelere yönelik.', NULL, 'treatment', 'Glycolic Acid, Viniferine', 'Night', 'Daily', 'Increases sun sensitivity. Use sunscreen during the day.', ARRAY['Normal','Combination']::text[], true),
  ('7ee5272f-4d63-52b2-bd25-1a63878415b1'::uuid, 'Cleanance Comedomed Exfoliating Care', 'Avène', 'Aimed at the clogged pores that turn into spots later, so it works before the breakout rather than after.', 'Sonradan sivilceye dönüşen tıkalı gözeneklere yönelik; sivilce çıktıktan sonra değil, öncesinde çalışıyor.', NULL, 'treatment', 'Comedoclastin, Avene Thermal Spring Water', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Combination','Sensitive']::text[], true),
  ('0d57441e-9d1d-5e8d-9196-850f03b22063'::uuid, 'Soothing Hydrating Mask', 'Avène', 'A calming mask for skin that has been pushed too hard. Leave it on as a thick layer and tissue off the excess.', 'Fazla zorlanmış ciltler için yatıştırıcı maske. Kalın bir katman halinde bırak, fazlasını peçeteyle al.', NULL, 'treatment', 'Avene Thermal Spring Water, Glycerin', 'Night', '1-2 times a week', NULL, ARRAY['Sensitive','Dry','Normal']::text[], true),
  ('15fe4965-7397-5f83-a2c7-5c768f2a8b87'::uuid, 'Cicabio Repairing Cream', 'Bioderma', 'A repair cream for small damaged areas after shaving, waxing or a rough patch of weather.', 'Tıraş, ağda ya da sert hava sonrası küçük hasarlı bölgeler için onarıcı krem.', NULL, 'treatment', 'Antalgicine, Copper, Zinc, Hyaluronic Acid', 'Night', 'As needed', NULL, ARRAY['Sensitive','Dry','Normal']::text[], true),
  ('a23956e5-9666-5746-bce8-44d887e5f9bf'::uuid, 'Hydrabio Hydrating Mask', 'Bioderma', 'A weekly hydration mask for skin that drinks up moisturiser and still feels tight by evening.', 'Nemlendiriciyi içip yine de akşama gergin hisseden ciltler için haftalık nem maskesi.', 'https://images.openbeautyfacts.org/images/products/340/134/361/3730/front_en.4.full.jpg', 'treatment', 'Aquagenium, Hyaluronic Acid', 'Night', '1-2 times a week', NULL, ARRAY['Dry','Normal','Sensitive']::text[], true),
  ('dcbcea41-9dd6-520b-bb47-2a953278c019'::uuid, 'Hyseac Purifying Mask', 'Uriage', 'Clay that pulls out congestion without leaving the whole face stripped. Rinse before it fully cracks.', 'Tüm yüzü soymadan tıkanıklığı çeken kil. Tamamen çatlamadan önce durula.', NULL, 'treatment', 'Kaolin, Uriage Thermal Water, Zinc', 'Night', '1-2 times a week', NULL, ARRAY['Oily','Combination']::text[], true),
  ('b8554d6c-1bdd-594f-8eb2-56b1df836a6a'::uuid, 'Hyseac SOS Paste Local Care', 'Uriage', 'A thick paste for one stubborn spot overnight. Dab on the spot only, not the surrounding skin.', 'Tek bir inatçı sivilce için gecelik kalın bir macun. Sadece sivilcenin üzerine sür, çevresine değil.', NULL, 'treatment', 'Zinc, Sulphur, Thermal Water', 'Night', 'As needed', NULL, ARRAY['Oily','Combination']::text[], true),
  ('6094c764-aa3a-5915-99bf-a90afe75dba1'::uuid, 'NCEF Night Mask', 'Filorga', 'A leave on overnight mask for the weeks when your face looks tired no matter how much you sleep.', 'Ne kadar uyursan uyu yüzünün yorgun göründüğü haftalar için, gece boyunca kalan bir maske.', NULL, 'treatment', 'NCEF Complex, Hyaluronic Acid', 'Night', '1-2 times a week', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('5226add8-35fb-50b9-afdd-98414ba8b613'::uuid, 'Pure Active Charcoal Mask', 'Garnier', 'An affordable clay and charcoal mask for blackheads around the nose and chin.', 'Burun ve çene çevresindeki siyah noktalar için uygun fiyatlı kil ve kömür maskesi.', NULL, 'treatment', 'Charcoal, Salicylic Acid, Kaolin', 'Night', '1-2 times a week', NULL, ARRAY['Oily','Combination']::text[], true),
  ('db2d540e-037e-55cf-bd17-ab1e77e08290'::uuid, 'Moisturizing Cream', 'CeraVe', 'A thick tub cream that slowly releases moisture through the night. Heavier than most day creams, which is the point.', 'Gece boyunca nemi yavaşça salan, kavanozda kalın bir krem. Çoğu gündüz kreminden ağır, zaten amacı da bu.', NULL, 'moisturizer', 'Ceramides, Hyaluronic Acid, MVE Technology', 'Night', 'Daily', NULL, ARRAY['Dry','Normal','Sensitive']::text[], true),
  ('ba7a5152-e894-55fe-abf8-c64e51542728'::uuid, 'PM Facial Moisturizing Lotion', 'CeraVe', 'A light night lotion for skin that does not want a heavy cream. Absorbs quickly enough that it will not transfer to your pillow.', 'Ağır krem istemeyen ciltler için hafif gece losyonu. Yastığa bulaşmayacak kadar hızlı emiliyor.', 'https://images.openbeautyfacts.org/images/products/360/600/053/7453/front_en.3.full.jpg', 'moisturizer', 'Ceramides, Niacinamide, Hyaluronic Acid', 'Night', 'Daily', NULL, ARRAY['Normal','Combination','Oily']::text[], true),
  ('e850b50d-1710-56c2-84ec-b77d64e0341d'::uuid, 'Skin Renewing Night Cream', 'CeraVe', 'A richer night cream with peptides, aimed at skin that is starting to look thinner around the eyes and cheeks.', 'Peptit içeren daha zengin bir gece kremi; göz ve yanak çevresinde incelmeye başlayan ciltler için.', NULL, 'moisturizer', 'Peptide Complex, Ceramides, Niacinamide', 'Night', 'Daily', NULL, ARRAY['Dry','Normal']::text[], true),
  ('1233203b-42ef-5a7e-a7e4-97af77b82dd2'::uuid, 'Toleriane Ultra Soothing Cream', 'La Roche-Posay', 'A minimal formula in a sterile pump for skin that reacts to almost everything. No preservatives, no fragrance.', 'Neredeyse her şeye tepki veren ciltler için steril pompada minimal bir formül. Koruyucu ve parfüm yok.', 'https://images.openbeautyfacts.org/images/products/333/787/575/7614/front_fr.5.400.jpg', 'moisturizer', 'Neurosensine, Thermal Spring Water, Shea Butter', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive','Dry']::text[], true),
  ('7ec2e7f4-1c8f-587f-a20b-c10258354224'::uuid, 'Hydraphase HA Light', 'La Roche-Posay', 'A light gel cream for daytime hydration that will not pill under sunscreen.', 'Güneş kreminin altında topaklanmayan, gündüz nemlendirmesi için hafif jel krem.', NULL, 'moisturizer', 'Hyaluronic Acid, Thermal Spring Water', 'Morning', 'Daily', NULL, ARRAY['Normal','Combination','Oily']::text[], true),
  ('6e122d1b-20e0-5155-8111-bd33da8038bd'::uuid, 'Hydrance Optimale Hydrating Cream', 'Avène', 'Made for dehydrated skin that is also sensitive. Keeps water in without a long ingredient list to react to.', 'Hem susuz hem hassas ciltler için. Tepki verilecek uzun bir içerik listesi olmadan suyu içeride tutuyor.', NULL, 'moisturizer', 'Avene Thermal Spring Water, Cohederm', 'Morning & Night', 'Daily', NULL, ARRAY['Dry','Sensitive','Normal']::text[], true),
  ('d2ec5c93-9802-5a27-9ca5-b4713a766ff6'::uuid, 'Tolerance Control Soothing Cream', 'Avène', 'Nine ingredients, sterile packaging, nothing else. For skin in the middle of a bad reactive stretch.', 'Dokuz içerik, steril ambalaj, başka bir şey yok. Kötü bir tepki döneminin ortasındaki ciltler için.', NULL, 'moisturizer', 'D-Sensinose, Sterile Cosmetics', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive']::text[], true),
  ('78c42f30-bb83-5a66-96e5-31af00e75951'::uuid, 'Cicalfate+ Repairing Protective Cream', 'Avène', 'A protective repair cream for small areas that need covering while they settle down.', 'Sakinleşene kadar kapatılması gereken küçük bölgeler için koruyucu onarım kremi.', NULL, 'moisturizer', 'Cu-Zn Complex, Postbiotic, Sucralfate', 'Night', 'As needed', NULL, ARRAY['Sensitive','Dry']::text[], true),
  ('bcd7686b-3b5c-5521-9ca6-3c3580fabb88'::uuid, 'Sebium Sensitive Soothing Care', 'Bioderma', 'For oily skin that has become irritated from acne treatments. Hydrates and calms without adding shine.', 'Sivilce tedavilerinden tahriş olmuş yağlı ciltler için. Parlaklık eklemeden nemlendiriyor ve yatıştırıyor.', NULL, 'moisturizer', 'Zinc, Enoxolone, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Oily','Sensitive','Combination']::text[], true),
  ('c1fa6904-d274-59c4-8761-0c29d6725ad5'::uuid, 'Sensibio Defensive Cream', 'Bioderma', 'A daily cream for sensitive skin that needs something under makeup or sunscreen without feeling heavy.', 'Makyaj ya da güneş kreminin altına ağırlık hissi vermeden girecek bir şey arayan hassas ciltler için günlük krem.', NULL, 'moisturizer', 'Toleridine, Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive','Normal','Dry']::text[], true),
  ('5e434ea4-3379-5300-9d6e-d12b1347dc89'::uuid, 'Aqualia Thermal Rehydrating Cream', 'Vichy', 'A steady, unfussy moisturiser. Comes in light and rich versions so you can match it to the season.', 'Sade ve istikrarlı bir nemlendirici. Hafif ve zengin versiyonları var, mevsime göre seçebilirsin.', NULL, 'moisturizer', 'Hyaluronic Acid, Vichy Mineralizing Water', 'Morning & Night', 'Daily', NULL, ARRAY['Dry','Normal','Sensitive']::text[], true),
  ('f1b6b9c5-bdda-5942-92f2-80d82c87a028'::uuid, 'Liftactiv Collagen Specialist', 'Vichy', 'A day cream for firmness and tone, aimed at skin where lines have started staying put after you stop smiling.', 'Sıkılık ve ton için gündüz kremi; gülümsemeyi bıraktıktan sonra da çizgileri kalmaya başlayan ciltler için.', NULL, 'moisturizer', 'Biopeptides, Vitamin C, Rhamnose', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('164dfef5-b61c-5a79-a54f-72c34379c7fa'::uuid, 'Moisturizing Cream', 'Cetaphil', 'A plain, heavy cream with no fragrance. Does one job and does it reliably.', 'Parfümsüz, sade ve ağır bir krem. Tek bir işi var ve onu güvenilir şekilde yapıyor.', NULL, 'moisturizer', 'Glycerin, Panthenol, Sweet Almond Oil', 'Night', 'Daily', NULL, ARRAY['Dry','Sensitive']::text[], true),
  ('8aab23e5-7629-5182-8331-a310810f8170'::uuid, 'Rich Night Cream', 'Cetaphil', 'For nights when a lotion is not enough, especially in heated rooms through winter.', 'Losyonun yetmediği geceler için; özellikle kışın kaloriferli odalarda.', 'https://images.openbeautyfacts.org/images/products/502/046/520/1700/front_en.5.full.jpg', 'moisturizer', 'Shea Butter, Vitamin E, Glycerin', 'Night', 'Daily', NULL, ARRAY['Dry','Normal']::text[], true),
  ('fac1ace7-fd0b-59ce-a6d7-2f0872fe19a2'::uuid, 'Hydro Boost Water Gel', 'Neutrogena', 'A gel that feels like water going on and disappears in seconds. Good summer moisturiser for oily skin.', 'Su gibi sürülen ve saniyeler içinde kaybolan bir jel. Yağlı ciltler için iyi bir yaz nemlendiricisi.', 'https://images.openbeautyfacts.org/images/products/357/466/155/4280/front_nl.13.full.jpg', 'moisturizer', 'Hyaluronic Acid, Glycerin', 'Morning', 'Daily', NULL, ARRAY['Normal','Combination','Oily']::text[], true),
  ('e7729d0d-693a-5f46-b204-e2c448540942'::uuid, 'Bright Boost Gel Cream', 'Neutrogena', 'A moisturiser with a mild resurfacing action, so tone evens out without adding a separate acid step.', 'Hafif yenileyici etkili bir nemlendirici; ayrı bir asit adımı eklemeden ton eşitleniyor.', NULL, 'moisturizer', 'Neoglucosamine, Mandelic Acid', 'Morning', 'Daily', NULL, ARRAY['Normal','Combination','Oily']::text[], true),
  ('bb0433ab-307b-5c4c-8b3a-dd2fc5c63b6b'::uuid, 'Natural Moisturizing Factors + HA', 'The Ordinary', 'A basic moisturiser with nothing active in it, which makes it the safe partner for a strong serum.', 'İçinde aktif bulunmayan temel bir nemlendirici; güçlü bir serumun yanına güvenle konur.', 'https://images.openbeautyfacts.org/images/products/076/991/519/0731/front_en.3.full.jpg', 'moisturizer', 'Amino Acids, Hyaluronic Acid, Ceramides', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('f4fbf679-2784-5c7d-96ba-59bf006439ba'::uuid, 'Hyaluron-Filler 3x Effect Day Cream', 'Eucerin', 'A day cream aimed at deeper set lines rather than surface dryness. Sits well under makeup.', 'Yüzeysel kurulukdan çok yerleşmiş çizgilere yönelik gündüz kremi. Makyajın altında iyi duruyor.', NULL, 'moisturizer', 'Hyaluronic Acid, Glycine Saponin, Enoxolone', 'Morning', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('1eb05b8e-cceb-5b02-b78e-800e8b15cb01'::uuid, 'Vinosource SOS Intense Moisturizing Cream', 'Caudalie', 'A rescue cream for skin that has gone dry and dull at the same time, usually after travel or illness.', 'Aynı anda hem kuruyup hem matlaşan ciltler için kurtarıcı krem; genellikle seyahat ya da hastalık sonrası.', NULL, 'moisturizer', 'Grape Water, Grape Seed Polyphenols', 'Morning & Night', 'Daily', NULL, ARRAY['Dry','Sensitive']::text[], true),
  ('a938bbe4-730c-513a-8a4e-fc65e41dc913'::uuid, 'Creme Fraiche de Beaute', 'Nuxe', 'A soft, cool textured cream for everyday use. Nothing dramatic, which is often what a routine needs.', 'Günlük kullanım için yumuşak ve serin dokulu bir krem. Dramatik bir şey yok, ki rutinin ihtiyacı genellikle bu.', NULL, 'moisturizer', 'Plant Milk, Vegetal Glycerin', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Sensitive','Dry']::text[], true),
  ('9f9599e1-cfc2-5d31-9f11-4618345f819c'::uuid, 'Extra-Firming Emulsion', 'Clarins', 'A firming emulsion in a lighter texture than the cream, for people who dislike a heavy finish.', 'Kremden daha hafif dokuda sıkılaştırıcı emülsiyon; ağır bir bitiş sevmeyenler için.', 'https://images.openbeautyfacts.org/images/products/366/605/727/2967/front_en.5.full.jpg', 'moisturizer', 'Kangaroo Flower Extract, Plant Extracts', 'Morning', 'Daily', NULL, ARRAY['Combination','Normal','Oily']::text[], true),
  ('e8807b3e-ae9c-55a8-850e-9be8891525ff'::uuid, 'Iris Hydrating Day Cream', 'Weleda', 'A plant based day cream with a light finish, certified natural if that matters to you.', 'Hafif bitişli, bitki bazlı bir gündüz kremi; senin için önemliyse doğal sertifikalı.', NULL, 'moisturizer', 'Iris Root Extract, Jojoba Oil', 'Morning', 'Daily', NULL, ARRAY['Normal','Combination']::text[], true),
  ('ab43c966-0ff3-563b-8449-616d4701667d'::uuid, 'Skin Renewing Eye Cream', 'CeraVe', 'A fragrance free eye cream for the crepey look that shows up under the lower lid. Pat it on with a ring finger.', 'Alt göz kapağında beliren buruşuk görünüm için parfümsüz göz kremi. Yüzük parmağıyla hafifçe bastırarak uygula.', NULL, 'eye_cream', 'Peptide Complex, Ceramides, Hyaluronic Acid', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Sensitive']::text[], true),
  ('560cd8db-962c-506a-a95d-e080c3fdd455'::uuid, 'Hydro Boost Awakening Eye Cream', 'Neutrogena', 'A light gel for mornings when the under eye area looks puffy and creases when you smile.', 'Göz altının şiş göründüğü ve gülünce kırıştığı sabahlar için hafif jel.', NULL, 'eye_cream', 'Hyaluronic Acid, Glycerin', 'Morning', 'Daily', NULL, ARRAY['Normal','Combination','Dry']::text[], true),
  ('bbab49e9-6a12-5ecb-9379-07a38414304f'::uuid, 'Vitamin C Brightening Eye Cream', 'Garnier', 'Caffeine for puffiness and vitamin C for the dull grey tone that comes with short nights.', 'Şişlik için kafein, kısa gecelerin getirdiği mat gri ton için C vitamini.', NULL, 'eye_cream', 'Vitamin C, Caffeine, Banana Powder', 'Morning', 'Daily', NULL, ARRAY['Normal','Combination','Oily']::text[], true),
  ('aa5189c2-3383-576d-8689-e4201eaaf3f7'::uuid, 'Resveratrol Lift Eye Lifting Balm', 'Caudalie', 'A firming eye balm for the lid area, aimed at loss of tone rather than dark circles.', 'Göz kapağı bölgesi için sıkılaştırıcı balm; koyu halkalardan çok tonus kaybına yönelik.', 'https://images.openbeautyfacts.org/images/products/352/293/003/1871/front_fr.11.full.jpg', 'eye_cream', 'Resveratrol, Hyaluronic Acid, Caffeine', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('ea7fbea6-c8ab-5cab-a07b-348679a52bbd'::uuid, 'Hydrating Eye Contour Cream', 'Weleda', 'A simple hydrating eye cream with a natural formulation, gentle enough for contact lens wearers.', 'Doğal formüllü, sade bir nemlendirici göz kremi; lens kullananlar için yeterince yumuşak.', NULL, 'eye_cream', 'Iris Extract, Jojoba Oil', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Sensitive']::text[], true),
  ('835fe836-a6fc-50a0-a09a-9c3ff5328451'::uuid, 'Kind To Skin Soothing Eye Balm', 'Simple', 'No fragrance, no dye, nothing that usually irritates the eye area. A safe starting point.', 'Parfüm yok, boya yok, göz çevresini genelde tahriş eden hiçbir şey yok. Güvenli bir başlangıç noktası.', NULL, 'eye_cream', 'Vitamin B5, Vitamin E, Bisabolol', 'Morning & Night', 'Daily', NULL, ARRAY['Sensitive','Normal','Dry']::text[], true),
  ('26ac0e27-fb5b-5cc3-9596-afd6896b7b2d'::uuid, 'Anti-Age Eye Cream', 'Clinique', 'An eye cream focused on the fine lines at the outer corner. Allergy tested and fragrance free.', 'Göz kenarındaki ince çizgilere odaklanan bir göz kremi. Alerji testli ve parfümsüz.', 'https://images.openbeautyfacts.org/images/products/002/071/438/2742/front_en.8.full.jpg', 'eye_cream', 'Peptides, Hyaluronic Acid, Vitamin C', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('39e75860-da19-5013-a74f-981ad1a40eba'::uuid, 'GinZing Refreshing Eye Cream', 'Origins', 'A brightening morning eye cream with a slight tint that cancels grey shadows under the eye.', 'Göz altındaki gri gölgeleri kapatan hafif renkli, aydınlatıcı sabah göz kremi.', 'https://images.openbeautyfacts.org/images/products/071/733/425/5012/front_en.11.400.jpg', 'eye_cream', 'Caffeine, Ginseng, Magnolia Extract', 'Morning', 'Daily', NULL, ARRAY['Normal','Combination','Oily']::text[], true),
  ('e4f83d72-59c4-5ff3-907d-ee78c14a9d90'::uuid, 'Banana Bright+ Eye Creme', 'Ole Henriksen', 'A brightening eye cream that also works as a base under concealer, which cuts a step on busy mornings.', 'Kapatıcı altına baz olarak da çalışan aydınlatıcı göz kremi; yoğun sabahlarda bir adım kazandırıyor.', 'https://images.openbeautyfacts.org/images/products/200/000/015/2396/front_en.3.full.jpg', 'eye_cream', 'Vitamin C, Collagen, Banana Powder', 'Morning', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('21e136c4-5a7d-5187-9d6d-069bd929a81a'::uuid, 'Eye Contour Cream', 'The Body Shop', 'A basic, affordable hydrating eye cream. Nothing complicated, which suits a first eye product.', 'Temel ve uygun fiyatlı bir nemlendirici göz kremi. Karmaşık bir şey yok, ilk göz ürünü olarak uygun.', NULL, 'eye_cream', 'Vitamin E, Community Trade Shea Butter', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry']::text[], true),
  ('f2e02901-ae77-5e28-96ef-df082cb0b628'::uuid, 'Nectar de Roses Cooling Eye Gel', 'Melvita', 'A cool gel with a metal applicator, aimed at morning puffiness. Keep it in the fridge for more effect.', 'Metal aplikatörlü serin jel; sabah şişkinliğine yönelik. Daha etkili olması için buzdolabında sakla.', NULL, 'eye_cream', 'Organic Rose Water, Cornflower, Caffeine', 'Morning', 'Daily', NULL, ARRAY['Normal','Combination','Sensitive']::text[], true),
  ('4c9a92ad-f843-5412-850c-8e3252d286cd'::uuid, 'Peptide Firming Eye Cream', 'Facetheory', 'A peptide focused eye cream at a low price, fragrance free and vegan.', 'Uygun fiyatlı, peptit odaklı göz kremi; parfümsüz ve vegan.', NULL, 'eye_cream', 'Matrixyl 3000, Caffeine, Hyaluronic Acid', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('86be636b-b1f5-5a5a-9e96-0bf64f683c6d'::uuid, 'Expert Anti-Ageing Eye Contour', 'Novexpert', 'A short ingredient list for the eye area, made for people who react to most eye creams.', 'Göz çevresi için kısa içerik listesi; çoğu göz kremine tepki verenler için.', NULL, 'eye_cream', 'Hyaluronic Acid, Vitamin C, Boswellia', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Sensitive','Dry']::text[], true),
  ('aa3f64a3-4c91-5d96-83d0-ccb9a66d6216'::uuid, 'Revitalift Filler Eye Serum', 'L''Oréal', 'A serum with a rollerball tip for the under eye. Lighter than a cream, so it layers under one if you need both.', 'Göz altı için roll-on uçlu bir serum. Kremden hafif, ikisine de ihtiyacın varsa kremin altına giriyor.', NULL, 'eye_serum', 'Hyaluronic Acid, Caffeine', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Dry','Combination']::text[], true),
  ('2b5d3f40-084f-54f3-8478-d8b75597c3d3'::uuid, 'Guava Eye Serum', 'Dr. Organic', 'A plant based eye serum with a light gel texture, suited to skin that finds eye creams too rich.', 'Hafif jel dokulu, bitki bazlı göz serumu; göz kremlerini fazla ağır bulan ciltler için.', NULL, 'eye_serum', 'Guava Extract, Aloe Vera, Hyaluronic Acid', 'Morning & Night', 'Daily', NULL, ARRAY['Normal','Combination','Sensitive']::text[], true),
  ('7471b946-3b2f-5475-ba28-f168e29d31c9'::uuid, 'Anthelios UVMune 400 Fluid SPF50+', 'La Roche-Posay', 'Covers a longer stretch of UVA than most filters, which matters if you are working on dark patches. Very light finish.', 'Çoğu filtreden daha geniş bir UVA aralığını kapatıyor; koyu lekeler üzerinde çalışıyorsan bu önemli. Çok hafif bir bitiş bırakıyor.', NULL, 'sunscreen', 'Mexoryl 400, Thermal Spring Water', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Combination','Sensitive']::text[], true),
  ('93abd479-8daa-5026-b385-15df86475409'::uuid, 'Anthelios Shaka Fluid SPF50+', 'La Roche-Posay', 'A fluid that dries down matte, so it is one of the easier high factor sunscreens to wear under makeup.', 'Mat kuruyan bir fluid; makyaj altına sürülebilecek en kolay yüksek faktörlü güneş kremlerinden biri.', NULL, 'sunscreen', 'Mexoryl XL, Netlock Technology', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Oily','Combination']::text[], true),
  ('714f4fb0-ad09-5b71-b476-b2b03017f7c0'::uuid, 'Anthelios Anti-Imperfections Gel-Cream SPF50+', 'La Roche-Posay', 'Sunscreen for blemish prone skin that usually avoids SPF because it feels heavy. Matte and non comedogenic.', 'Ağır geldiği için genelde güneş kreminden kaçınan, sivilceye eğilimli ciltler için. Mat ve gözenek tıkamayan.', NULL, 'sunscreen', 'Mexoryl, Airlicium, Salicylic Acid', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Oily','Combination']::text[], true),
  ('41d7f536-d1c3-5772-9d67-7ac17c62a211'::uuid, 'Photoderm Max Aquafluide SPF50+', 'Bioderma', 'A watery fluid that vanishes on the skin. One of the better options if you dislike the usual sunscreen feel.', 'Ciltte kaybolan su kıvamında bir fluid. Alışıldık güneş kremi hissini sevmiyorsan en iyi seçeneklerden biri.', NULL, 'sunscreen', 'Cellular Bioprotection, Vitamin E', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Combination','Oily']::text[], true),
  ('cc6a5e01-28ab-5894-9af5-ad4cc83204fd'::uuid, 'Photoderm Spot-Age SPF50+', 'Bioderma', 'Combines high protection with antioxidants, made for skin already showing sun marks.', 'Yüksek korumayı antioksidanlarla birleştiriyor; halihazırda güneş lekesi olan ciltler için.', NULL, 'sunscreen', 'Vitamin C, Vitamin E, Bioprotection Complex', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Combination','Dry']::text[], true),
  ('f98e5545-b047-51ae-bc14-b617a05f0516'::uuid, 'Very High Protection Ultra Fluid SPF50+', 'Avène', 'A fluid built for sensitive skin, with a short filter list and no fragrance.', 'Hassas ciltler için hazırlanmış fluid; kısa filtre listesi ve parfümsüz.', NULL, 'sunscreen', 'Tinosorb, Avene Thermal Spring Water', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Sensitive','Normal','Combination']::text[], true),
  ('e60ebe90-6dd0-5a06-b68a-ad8561168944'::uuid, 'Antirougeurs Rosamed SPF50+', 'Avène', 'Sun protection for skin with persistent facial redness, where heat and light make things worse.', 'Sıcağın ve ışığın durumu kötüleştirdiği, kalıcı yüz kızarıklığı olan ciltler için güneş koruması.', NULL, 'sunscreen', 'Thermal Spring Water, Ruscus Extract', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Sensitive','Dry','Normal']::text[], true),
  ('00c42cf9-a1a4-56c8-a59c-5b774f5b6585'::uuid, 'Capital Soleil UV Age Daily SPF50+', 'Vichy', 'A daily sunscreen that doubles as an anti ageing step, which makes it easier to actually wear it every day.', 'Yaşlanma karşıtı adım olarak da çalışan günlük güneş kremi; her gün sürmeyi gerçekten kolaylaştırıyor.', NULL, 'sunscreen', 'Netlock, Niacinamide, Peptides', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Combination','Dry']::text[], true),
  ('543b148a-8391-5303-8c38-87db126c3330'::uuid, 'Ideal Soleil Face Fluid SPF30', 'Vichy', 'A mid factor daily fluid for city days when you are mostly indoors but still near windows.', 'Çoğunlukla içeride ama pencere kenarında geçen şehir günleri için orta faktörlü günlük fluid.', NULL, 'sunscreen', 'Vichy Thermal Water, UV Filters', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Combination']::text[], true),
  ('8324987d-335e-5562-951a-a999cb54e0fb'::uuid, 'Bariesun Mineral Cream SPF50+', 'Uriage', 'A mineral only filter for skin that reacts to chemical sunscreens. Leaves a slight white cast.', 'Kimyasal güneş kremlerine tepki veren ciltler için yalnızca mineral filtre. Hafif beyaz iz bırakıyor.', NULL, 'sunscreen', 'Titanium Dioxide, Uriage Thermal Water', 'Morning', 'Daily', 'May leave a white cast on deeper skin tones. Reapply every two hours in direct sun.', ARRAY['Sensitive','Dry','Normal']::text[], true),
  ('871dbe9f-3fd8-5954-ab2c-342efa419da5'::uuid, 'Hyseac 3-Regul Global Care SPF30', 'Uriage', 'A tinted care with SPF for oily skin, so moisturiser, sunscreen and a little coverage happen in one step.', 'Yağlı ciltler için SPF içeren renkli bakım; nemlendirici, güneş koruması ve hafif kapatıcılık tek adımda.', NULL, 'sunscreen', 'TLR2-Regul, Zinc, UV Filters', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Oily','Combination']::text[], true),
  ('7474688d-4685-5f10-a6d9-7094c56d21d5'::uuid, 'AM Facial Moisturizing Lotion SPF30', 'CeraVe', 'A moisturiser with SPF30 built in. Fine for indoor days, though a dedicated sunscreen is better in strong sun.', 'İçinde SPF30 olan bir nemlendirici. İçeride geçen günler için yeterli, güçlü güneşte ayrı bir güneş kremi daha iyi.', 'https://images.openbeautyfacts.org/images/products/079/337/924/5584/front_en.3.full.jpg', 'sunscreen', 'Ceramides, Niacinamide, Hyaluronic Acid', 'Morning', 'Daily', 'Not enough on its own for extended time outdoors.', ARRAY['Normal','Dry','Combination']::text[], true),
  ('ca2079d3-cd06-5034-84c7-c54a74781151'::uuid, 'Clear Face Sunscreen SPF50', 'Neutrogena', 'Oil free and non comedogenic, made specifically so that daily sunscreen does not cause breakouts.', 'Yağsız ve gözenek tıkamayan; günlük güneş kremi sivilceye sebep olmasın diye özel olarak tasarlanmış.', NULL, 'sunscreen', 'Helioplex, Oil-Free Filters', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Oily','Combination']::text[], true),
  ('8fd14f6d-58e3-5048-8997-1e15324756b8'::uuid, 'Ultra Sheer Dry-Touch Sunscreen', 'Neutrogena', 'A dry finish sunscreen that does not stay tacky, which is why it is a common daily pick.', 'Yapış yapış kalmayan, kuru bitişli güneş kremi; günlük kullanımda bu yüzden sık tercih ediliyor.', NULL, 'sunscreen', 'Helioplex, Avobenzone', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Combination','Oily']::text[], true),
  ('0564dcf5-5b1c-52f8-9a9f-545b5137ff5a'::uuid, 'Sun Gel-Cream Oil Control SPF50+', 'Eucerin', 'Absorbs oil through the day, so the shine that usually appears by lunchtime stays down.', 'Gün boyunca yağı emiyor, öğlene doğru beliren parlaklığı bastırıyor.', NULL, 'sunscreen', 'Licochalcone A, L-Carnitine, Oil Control Complex', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Oily','Combination']::text[], true),
  ('a5538225-54e9-592d-9542-0c208654bc7c'::uuid, 'UV-Bronze Anti-Ageing Sun Fluid SPF50+', 'Filorga', 'A sunscreen with an anti ageing complex for people who want one product instead of two in the morning.', 'Sabahları iki ürün yerine tek ürün isteyenler için yaşlanma karşıtı kompleks içeren güneş kremi.', NULL, 'sunscreen', 'NCEF Complex, UV Filters, Antioxidants', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Dry','Combination']::text[], true),
  ('3da3a023-8f02-5c95-aebe-779c1bd85229'::uuid, 'Vinosun Protect Invisible Fluid SPF50+', 'Caudalie', 'An invisible fluid with a short filter list and reef safe filters, for skin that dislikes heavy textures.', 'Kısa filtre listesi ve mercan dostu filtrelerle görünmez bir fluid; ağır dokuları sevmeyen ciltler için.', NULL, 'sunscreen', 'Grape Seed Polyphenols, Vitamin E', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Sensitive','Normal','Dry']::text[], true),
  ('d9b60c3b-8395-567e-91fd-25e31c5b1ac5'::uuid, 'SkinActive Super UV Glow Fluid SPF50+', 'Garnier', 'An affordable daily fluid with vitamin C, which makes high factor protection easier to keep up with.', 'C vitaminli, uygun fiyatlı günlük fluid; yüksek faktörlü korumayı sürdürmeyi kolaylaştırıyor.', 'https://images.openbeautyfacts.org/images/products/360/054/259/9597/front_nl.9.full.jpg', 'sunscreen', 'Vitamin C, Niacinamide, UV Filters', 'Morning', 'Daily', 'Reapply every two hours in direct sun.', ARRAY['Normal','Combination','Dry']::text[], true)
